const input = $('When Executed by Another Workflow').first().json;
const rawOutput = $input.first().json;

// Try to extract the text from OpenAI response
let responseText = '';
if (rawOutput.message && rawOutput.message.content) {
  responseText = rawOutput.message.content;
} else if (rawOutput.choices && rawOutput.choices[0]) {
  responseText = rawOutput.choices[0].message.content;
} else if (typeof rawOutput === 'string') {
  responseText = rawOutput;
} else {
  responseText = JSON.stringify(rawOutput);
}

// Parse JSON from LLM response
let intent = 'unknown';
let confidence = 0;
let reason = 'parse_failed';

try {
  // Extract JSON from possible markdown code fences
  let jsonStr = responseText;
  const jsonMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) jsonStr = jsonMatch[1].trim();

  // Also try to find JSON object directly
  const objMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (objMatch) jsonStr = objMatch[0];

  const parsed = JSON.parse(jsonStr);
  intent = parsed.intent || 'unknown';
  confidence = parsed.confidence || 0;
  reason = parsed.reason || '';
} catch (e) {
  intent = 'unknown';
  confidence = 0;
  reason = 'LLM response was not valid JSON: ' + responseText.substring(0, 100);
}

// Hard override: #humano always -> human_handoff
const msgText = (input.message_text || '').toLowerCase();
if (msgText.includes('#humano')) {
  intent = 'human_handoff';
  confidence = 1.0;
  reason = 'Hard rule: message contains #humano';
}

// Validate intent is in allowed set
const allowed = ['greeting', 'kb_question', 'follow_up', 'human_handoff', 'unsupported', 'unknown'];
if (!allowed.includes(intent)) {
  intent = 'unknown';
  reason = 'Invalid intent from LLM: ' + intent;
}

return [{ json: { intent, confidence, reason } }];
